/****************************************************************************
 * Name: nxsig_lowest
 *
 * Description:
 *   Return the lowest signal number that is a member of a set of signals.
 *
 ****************************************************************************/

int nxsig_lowest(sigset_t *set)
{
  int signo;

  for (signo = MIN_SIGNO; signo <= MAX_SIGNO; signo++)
    {
      if (nxsig_ismember(set, signo))
        {
          return signo;
        }
    }

  return ERROR;
}

